  const isThisLoading = loadingPlan === (shopifyPlan ?? "cancel");

  return (
    <Box
      background="bg-surface"
      borderWidth="025"
      borderColor="border"
      borderRadius="300"
      padding="0"
      overflowX="hidden"
      overflowY="hidden"
