                    <div style={{
                      border: "1px solid #d1d8e0",
                      borderRadius: 12,
                      overflow: "hidden",
                      background: "#f1f5f9",
                    }}>
                      {/* Browser chrome */}
                      <div style={{
                        height: 32,
                        background: "#e8edf2",
                        borderBottom: "1px solid #d1d8e0",
                        display: "flex",
                        alignItems: "center",
                        padding: "0 12px",
                        gap: 6,
                      }}>
                        <div style={{ width: 8, height: 8, borderRadius: "50%", background: "#ff5f57" }} />
                        <div style={{ width: 8, height: 8, borderRadius: "50%", background: "#febc2e" }} />
                        <div style={{ width: 8, height: 8, borderRadius: "50%", background: "#28c840" }} />
                      </div>
                      {/* Preview area */}
                      <div style={{
                        padding: 24,
                        background: "radial-gradient(circle, #d1d8e0 1px, transparent 1px)",
                        backgroundSize: "20px 20px",
                        backgroundColor: "#eef2f6",
                        display: "flex",
                        alignItems: "center",
                        justifyContent: "center",
                        minHeight: 340,
                      }}>
                        <WidgetPreview cfg={previewCfg} previewState={previewState} widgetFullCustom={limits.widgetFullCustom} showEtaCodReturn={limits.showEtaCodReturn} />
                      </div>
                    </div>
                  </BlockStack>
                </Card>
              </div>
            </InlineGrid>
          </Layout.Section>
        </Layout>
      </Box>
      {/* Reset Confirmation Modal */}
      <Modal
        open={resetModalOpen}
        onClose={() => setResetModalOpen(false)}
        title="Reset to default settings?"
        primaryAction={{
          content: "Reset to Defaults",
          onAction: handleResetConfirm,
          destructive: true,
        }}
        secondaryActions={[
          {
            content: "Cancel",
            onAction: () => setResetModalOpen(false),
          },
        ]}
      >
        <Modal.Section>
          <Text as="p" variant="bodyMd">
            This will erase all your current widget customizations (colors,
            messages, toggles, custom CSS) and restore the original default
            settings. This action cannot be undone.
          </Text>
        </Modal.Section>
      </Modal>
    </Page>
  );
}

export function ErrorBoundary() {
  return boundary.error(useRouteError());
}

export const headers: HeadersFunction = (headersArgs) => {
  return boundary.headers(headersArgs);
};

